package com.p2p.escrow.web;
import com.p2p.escrow.domain.*; import com.p2p.escrow.domain.Enums.*; import com.p2p.escrow.repo.Repositories.*; import com.p2p.escrow.service.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.*;
@RestController @RequestMapping("/api") public class ApiController { private final Orders orders;private final Users users;private final Wallets wallets;private final EscrowService escrow;private final TrustService trust; public ApiController(Orders o,Users u,Wallets w,EscrowService e,TrustService t){orders=o;users=u;wallets=w;escrow=e;trust=t;} private UUID me(Authentication a){return UUID.fromString(a.getName());} private AppUser user(Authentication a){return users.findById(me(a)).orElseThrow();}
 @GetMapping("/orders") public List<TradeOrder> orders(){return orders.active();} @PostMapping("/orders") public TradeOrder create(@Valid @RequestBody CreateOrder c,Authentication a){AppUser u=user(a);if(!trust.canTrade(u))throw new IllegalStateException("Verified KYC and active account required");if(c.fiatAmount.compareTo(BigDecimal.valueOf(trust.dailyLimit(u)))>0)throw new IllegalStateException("Trust tier limit exceeded");TradeOrder o=new TradeOrder();o.makerId=u.id;o.side=c.side;o.asset=c.asset.toUpperCase();o.cryptoAmount=c.cryptoAmount;o.fiatAmount=c.fiatAmount;o.fiatCurrency=c.fiatCurrency.toUpperCase();o.paymentMethods=String.join(",",c.paymentMethods);return orders.save(o);}
 @PostMapping("/orders/{id}/accept") public Escrow accept(@PathVariable UUID id,Authentication a){return escrow.accept(id,me(a));}@PostMapping("/escrows/{id}/paid") public Escrow paid(@PathVariable UUID id,Authentication a){return escrow.markPaid(id,me(a));}@PostMapping("/escrows/{id}/release") public Escrow release(@PathVariable UUID id,Authentication a){return escrow.release(id,me(a));}@PostMapping("/admin/escrows/{id}/resolve") public Escrow resolve(@PathVariable UUID id,@RequestParam boolean releaseToBuyer,Authentication a){if(user(a).role!=Role.ADMIN)throw new SecurityException("Admin only");return escrow.resolve(id,me(a),releaseToBuyer);}@GetMapping("/wallets") public List<Wallet> wallets(Authentication a){return wallets.findByUserId(me(a));}
 @ExceptionHandler({IllegalStateException.class,SecurityException.class}) ResponseEntity<Map<String,String>> error(Exception e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));} public record CreateOrder(@NotNull Side side,@NotBlank String asset,@NotNull @DecimalMin("0.00000001") BigDecimal cryptoAmount,@NotNull @DecimalMin("1") BigDecimal fiatAmount,@NotBlank String fiatCurrency,@NotEmpty List<String> paymentMethods){}
}
